using System.Collections.Generic;
using UnityEngine;
using MaxWorlds.Enemies;

namespace MaxWorlds.VFX
{
    /// <summary>The four materials every Backyard robot is built from. Three are SHARED across the
    /// whole roster — which is what makes seven kinds read as one family assembled from one shed —
    /// and only <see cref="Warm"/> varies, because it is the one carrying gameplay information.</summary>
    public readonly struct RobotPalette
    {
        /// <summary>The kind's own hue, straight from CharacterSkin. The gameplay colour code.</summary>
        public readonly Material Warm;
        /// <summary>Shared cool. Identical on every kind.</summary>
        public readonly Material Cool;
        /// <summary>Shared near-black: every joint, leg, claw, cable and eye bezel.</summary>
        public readonly Material Dark;
        /// <summary>The single Tier-1 gold tell. It foreshadows the Curator and only pays if withheld.</summary>
        public readonly Material Gold;

        /// <summary>MV-800: World 2's shared stormdrain shoulder-band material — null for every other
        /// skin/world, in which case <see cref="RobotBodies.Build"/> builds no band at all. Optional so
        /// every existing 4-argument caller (Sentinel, the EditMode tests) keeps compiling unchanged.
        /// MV-1231: also built (unconditionally, not skin-gated) for the Breaker's own hazard-striped
        /// chassis band — see <see cref="RobotRig.BuildMaterials"/>.</summary>
        public readonly Material Hazard;

        /// <summary>MV-1231: the Breaker's own red ram-head knuckle accent — null for every other kind,
        /// in which case <see cref="RobotBodies.BuildBreaker"/> (the only reader) would fall back to
        /// <see cref="Warm"/>.</summary>
        public readonly Material Accent;

        public RobotPalette(Material warm, Material cool, Material dark, Material gold,
                            Material hazard = null, Material accent = null)
        {
            Warm = warm; Cool = cool; Dark = dark; Gold = gold; Hazard = hazard; Accent = accent;
        }
    }

    /// <summary>
    /// Every Backyard robot's visible body, in metres, feet at y = 0 and +Z where it is running.
    ///
    /// Built from <see cref="CharacterMeshes"/>, not primitives — see that class for why. Two
    /// consequences worth knowing: the geometry is shared across every instance of a kind, so a
    /// swarm costs what one robot costs; and SIZE IS REAL here, because
    /// <c>ParentScale.MakeMetreSpace</c> cancels the archetype's body scale before any of this is
    /// placed. That cancellation is why Rusher, Heavy and Brute used to be the same size on screen
    /// despite three different <c>BodyScale</c> values.
    /// </summary>
    public static partial class RobotBodies
    {
        /// <summary>World 3's skin tag (MV-715/MV-746) — kept as its own copy rather than a shared
        /// constant, the same "one literal per file that needs it" idiom <see cref="CharacterSkin"/>
        /// and <see cref="MaxWorlds.Enemies.RobotEnemy"/> already use for it.</summary>
        private const string ReefSkinTag = "reef";

        /// <summary>World 2's skin tag (MV-701/MV-800) — same "one literal per file that needs it"
        /// idiom as <see cref="ReefSkinTag"/>.</summary>
        private const string StormdrainSkinTag = "stormdrain";

        /// <summary>World 5's skin tag (MV-1226) — same "one literal per file that needs it" idiom as
        /// <see cref="ReefSkinTag"/>. Deliberately NOT read by <see cref="MaxWorlds.VFX.RobotRig.BuildMaterials"/>
        /// the way <see cref="ReefSkinTag"/>/<see cref="StormdrainSkinTag"/> are — the Mothership keeps
        /// every kind's own roster colour (the ticket's own "Lee likes the roster's kind colours; keep
        /// them"), only the silhouette changes.</summary>
        private const string MothershipSkinTag = "mothership";

        /// <summary>Build <paramref name="kind"/>'s body under <paramref name="root"/> and return the
        /// emissive lenses the rig drives as its tell. <paramref name="skin"/> selects a world
        /// reskin's OWN silhouette (MV-746) — null/anything else falls through to the base roster.</summary>
        public static Body Build(EnemyKind kind, Transform root, in RobotPalette p, string skin = null)
        {
            var eyes = new List<MeshRenderer>(2);
            var wheels = new List<Transform>(6);
            var legs = new List<Transform>(4);
            Transform inflatable = null;
            Transform breakerChainPivot = null, breakerChainEnd = null, breakerWallAnchor = null;
            Transform visualRoot = VisualTrimRootFor(kind, root);

            if (skin == ReefSkinTag && TryBuildReef(kind, visualRoot, p, eyes, wheels, legs, out inflatable))
                return new Body(eyes.ToArray(), wheels.ToArray(), legs.ToArray(), inflatable);

            if (skin == MothershipSkinTag && TryBuildMothership(kind, visualRoot, p, eyes, wheels, legs))
                return new Body(eyes.ToArray(), wheels.ToArray(), legs.ToArray(), null);

            switch (kind)
            {
                case EnemyKind.Launcher: BuildLauncher(visualRoot, p, eyes, wheels, legs); break;
                case EnemyKind.Blinker:  BuildBlinker(visualRoot, p, eyes, wheels, legs); break;
                case EnemyKind.Gunner:   BuildGunner(visualRoot, p, eyes, wheels, legs); break;
                case EnemyKind.Bolter:   BuildBolter(visualRoot, p, eyes, wheels, legs); break;
                case EnemyKind.Lurker:   BuildLurker(visualRoot, p, eyes, wheels, legs); break;
                case EnemyKind.Turret:   BuildTurret(visualRoot, p, eyes, wheels, legs); break;
                case EnemyKind.Sludger:  BuildSludger(visualRoot, p, eyes, wheels, legs); break;
                case EnemyKind.Charger:  BuildCharger(visualRoot, p, eyes, wheels, legs); break;
                case EnemyKind.Dreadnought: BuildDreadnought(visualRoot, p, eyes, wheels, legs); break;
                case EnemyKind.Skitter:  BuildSkitter(visualRoot, p, eyes, wheels, legs); break;
                case EnemyKind.Breaker:  BuildBreaker(visualRoot, p, eyes, wheels, legs,
                                              out breakerChainPivot, out breakerChainEnd, out breakerWallAnchor); break;
                case EnemyKind.Tractor:  BuildTractor(visualRoot, p, eyes, wheels, legs); break;
                case EnemyKind.Welder:   BuildWelder(visualRoot, p, eyes, wheels, legs); break;
                case EnemyKind.Projector: BuildProjector(visualRoot, p, eyes, wheels, legs); break;
                case EnemyKind.Jammer:   BuildJammer(visualRoot, p, eyes, wheels, legs); break;
                case EnemyKind.Bruiser:  BuildBruiser(visualRoot, p, eyes, wheels, legs); break;
                case EnemyKind.Heavy:    BuildHeavy(visualRoot, p, eyes, wheels, legs); break;
                case EnemyKind.Brute:    BuildBrute(visualRoot, p, eyes, wheels, legs); break;
                default:                 BuildRusher(visualRoot, p, eyes, wheels, legs); break;
            }

            // MV-800: the shared faction signature, on top of whichever silhouette the switch above
            // just built — never a silhouette change of its own (ticket AC4).
            if (skin == StormdrainSkinTag) AddStormdrainShoulderBand(kind, visualRoot, p);

            return new Body(eyes.ToArray(), wheels.ToArray(), legs.ToArray(), null,
                            breakerChainPivot, breakerChainEnd, breakerWallAnchor);
        }

        /// <summary>MV-800: World 2's shared faction signature — a hazard-yellow band ringing every
        /// stormdrain-skinned body at 50% of its collider height, 0.085x its archetype's body scale
        /// tall, so eight different hues still read as one faction assembled from one shed. The
        /// Lurker's own single eye lens and gold neck ring (already built by <see cref="BuildLurker"/>)
        /// carry the rest of its read and are untouched; every other kind's own eye/status lens is
        /// untouched too. A no-op if the caller passed no <see cref="RobotPalette.Hazard"/> material.</summary>
        private static void AddStormdrainShoulderBand(EnemyKind kind, Transform root, in RobotPalette p)
        {
            if (p.Hazard == null) return;

            EnemyArchetype archetype = EnemyArchetype.Of(kind);
            float radius = archetype.ColliderRadius;
            float thickness = 0.085f * archetype.BodyScale.y;
            float y = archetype.ColliderHeight * 0.5f;

            Add(root, CharacterMeshes.Ring(radius * 0.82f, radius * 1.02f, thickness, 20), p.Hazard,
                new Vector3(0f, y, 0f), Quaternion.identity, Vector3.one, "StormdrainBand");
        }

        /// <summary>MV-669 revision 3: reverting Max's own +10% scale-up re-exposed a pre-existing
        /// YT-74 conflict — Heavy renders at 1.997 m, taller than the reverted Max (1.9876 m). Lee's
        /// call was to trim Heavy, not re-inflate Max. This is a SILHOUETTE-only fix: a scale pivot
        /// planted at y = 0 (ground, where every <c>Build*</c> method here already authors its feet),
        /// so shrinking about it cannot float or sink the robot, and it leaves
        /// <see cref="EnemyArchetype.BodyScale"/>/<c>ColliderHeight</c> — which drive the collider and
        /// the MV-434 body-separation clamp — completely untouched. No other kind is trimmed.</summary>
        private const float HeavyVisualTrim = 0.931f; // measured 1.997m -> ~1.859m, clears Max's 1.9876m by ~6.5%

        private static Transform VisualTrimRootFor(EnemyKind kind, Transform root)
        {
            if (kind != EnemyKind.Heavy) return root;

            var pivot = new GameObject("HeavyVisualTrim").transform;
            pivot.SetParent(root, worldPositionStays: false);
            pivot.localScale = Vector3.one * HeavyVisualTrim;
            return pivot;
        }

        /// <summary>What a built body hands back: the lenses the eye tell drives, the wheels the rig
        /// spins, and (MV-580) the legs a gait driver swings. Wheels/legs are returned rather than
        /// found by name because a name search is a silent-failure mode — rename a part and the robot
        /// stops rolling/walking with no error.</summary>
        public readonly struct Body
        {
            public readonly MeshRenderer[] Eyes;
            /// <summary>Every rolling part, already oriented so its LOCAL Y is the axle. Spin with
            /// <c>Rotate(Vector3.up, degrees, Space.Self)</c>.</summary>
            public readonly Transform[] Wheels;
            /// <summary>Every leg's HIP pivot (MV-580) — empty for a wheeled kind. Each pivot's local
            /// rotation is identity at rest, one rigid leg (every part authored for that leg) hanging
            /// beneath it, so a gait driver can swing the whole leg by rotating the pivot alone; see
            /// <see cref="MaxWorlds.VFX.LegGaitDriver"/>. Only <see cref="EnemyKind.Gunner"/> populates
            /// this today (the kind Max's Sentinel borrows its body from, MV-580) — the other legged
            /// kind, <see cref="EnemyKind.Blinker"/>, teleports rather than walking and so still has no
            /// need of one; wire it the same way here if a future mover needs it.</summary>
            public readonly Transform[] Legs;

            /// <summary>MV-746: the World 3 Puffer Mine's own inflatable-body transform, scaled up
            /// over its telegraph by <see cref="MaxWorlds.VFX.RobotRig"/>. Null for every other kind
            /// and every non-Reef build.</summary>
            public readonly Transform Inflatable;

            /// <summary>MV-1231: the Breaker's own collar-chain assembly, null for every other kind.
            /// <see cref="BreakerChainPivot"/> is the joint <see cref="MaxWorlds.VFX.RobotRig"/> rotates
            /// from its built (taut) pose to <see cref="BreakerChainSlackLocalRotation"/> the instant
            /// <see cref="MaxWorlds.Enemies.ChainSignals.ChainSnapped"/> fires for this robot;
            /// <see cref="BreakerChainEnd"/> (the broken link, a child of the pivot) is what moves;
            /// <see cref="BreakerWallAnchor"/> (a sibling of the pivot, under the same root, never
            /// moves) is what it was pinned to. Built so that, at the pivot's authored TAUT rotation,
            /// the end sits exactly on the anchor — see <see cref="BuildBreaker"/>.</summary>
            public readonly Transform BreakerChainPivot;
            public readonly Transform BreakerChainEnd;
            public readonly Transform BreakerWallAnchor;

            public Body(MeshRenderer[] eyes, Transform[] wheels, Transform[] legs, Transform inflatable = null,
                        Transform breakerChainPivot = null, Transform breakerChainEnd = null,
                        Transform breakerWallAnchor = null)
            {
                Eyes = eyes; Wheels = wheels; Legs = legs; Inflatable = inflatable;
                BreakerChainPivot = breakerChainPivot; BreakerChainEnd = breakerChainEnd;
                BreakerWallAnchor = breakerWallAnchor;
            }
        }

