            Add(root, CharacterMeshes.Lathe(new[] { new Vector2(0f, 0f), new Vector2(0.034f, 0.02f), new Vector2(0.041f, 0.05f), new Vector2(0f, 0.12f) }, 10), p.Gold, new Vector3(0.15f, 1.1125f, 0.1894f), Quaternion.Euler(74f, 0f, 0f), Vector3.one);
            Add(root, CharacterMeshes.Prism(7, 0.14f, 0.17f, 0.2f, 0.24f, 0f), p.Cool, new Vector3(0f, 0.62f, 0.2f), Quaternion.Euler(26f, 0f, 0f), Vector3.one);
            Add(root, CharacterMeshes.Lathe(new[] { new Vector2(0.0806f, 0f), new Vector2(0.1235f, 0.0126f), new Vector2(0.13f, 0.026f), new Vector2(0.117f, 0.042f) }, 24), p.Dark, new Vector3(0f, 0.62f, 0.31f), Quaternion.Euler(46f, 0f, 0f), Vector3.one);
            eyes.Add(Lens(root, CharacterMeshes.Sphere(20), new Vector3(0f, 0.6339f, 0.3244f), Quaternion.Euler(-44f, 0f, 0f), new Vector3(0.155f, 0.155f, 0.05f)));
            Add(root, CharacterMeshes.Beam(0.2f, 0.016f, 0.007f, 5), p.Dark, new Vector3(-0.17f, 1.28f, 0.1f), Quaternion.Euler(-9f, 0f, 14f), Vector3.one);
            Add(root, CharacterMeshes.Beam(0.14f, 0.016f, 0.007f, 5), p.Dark, new Vector3(0.18f, 1.23f, 0.08f), Quaternion.Euler(0f, 0f, -9f), Vector3.one);
            Add(root, CharacterMeshes.Sphere(10), p.Gold, new Vector3(0.2019f, 1.3f, 0.08f), Quaternion.identity, new Vector3(0.028f, 0.028f, 0.028f));
        }

        /// <summary>Blinker (MV-584 rework) — one of only two kinds that keeps legs, and it earns
        /// them: it teleports rather than closing on foot, so it never needs a walk cycle. Before this
        /// it wore no colour of its own (fell through to <see cref="CharacterSkin.RoleFor"/>'s Rusher
        /// default) and its faceted crystal core was small, mostly <c>p.Cool</c>/<c>p.Dark</c>, and sat
        /// on a narrow crossed-leg stance — at gameplay distance it read as just another dark blob, the
        /// Rusher with a different name. The core is now ~1.5x its old size and wears the kind's own
        /// BODY material throughout (magenta, once <see cref="CharacterSkin.RoleFor"/> maps
        /// <see cref="EnemyKind.Blinker"/> to its own role) rather than the shared cool/dark tones, the
        /// stance is widened to plant a bigger core, and three floating crystal shards orbit the core at
        /// head height — the at-a-glance tell that this is a crystal on legs, not a wheeled robot.</summary>
        private static void BuildBlinker(Transform root, in RobotPalette p,
                                    List<MeshRenderer> eyes, List<Transform> wheels, List<Transform> legs)
        {
            Add(root, CharacterMeshes.Beam(0.1541f, 0.03f, 0.024f, 7), p.Dark, new Vector3(-0.0805f, 0.228f, 0f), Quaternion.Euler(0f, 0f, 26.1301f), Vector3.one);
            Add(root, CharacterMeshes.Sphere(12), p.Dark, new Vector3(-0.042f, 0.156f, 0f), Quaternion.identity, new Vector3(0.069f, 0.069f, 0.069f));
            Add(root, CharacterMeshes.Beam(0.1561f, 0.024f, 0.02f, 7), p.Dark, new Vector3(-0.04452f, 0.078f, 0f), Quaternion.Euler(0f, 0f, 7.5f), Vector3.one);
            Add(root, CharacterMeshes.Lathe(new[] { new Vector2(0.038f, 0f), new Vector2(0.026f, 0.045f), new Vector2(0.01f, 0.075f) }, 8), p.Dark, new Vector3(-0.0462f, -0.03f, 0.03f), Quaternion.Euler(10f, 0f, 0f), Vector3.one);
            Add(root, CharacterMeshes.Beam(0.1541f, 0.03f, 0.024f, 7), p.Dark, new Vector3(0.0805f, 0.228f, 0f), Quaternion.Euler(0f, 0f, -26.1301f), Vector3.one);
            Add(root, CharacterMeshes.Sphere(12), p.Dark, new Vector3(0.042f, 0.156f, 0f), Quaternion.identity, new Vector3(0.069f, 0.069f, 0.069f));
            Add(root, CharacterMeshes.Beam(0.1561f, 0.024f, 0.02f, 7), p.Dark, new Vector3(0.04452f, 0.078f, 0f), Quaternion.Euler(0f, 0f, -7.5f), Vector3.one);
            Add(root, CharacterMeshes.Lathe(new[] { new Vector2(0.038f, 0f), new Vector2(0.026f, 0.045f), new Vector2(0.01f, 0.075f) }, 8), p.Dark, new Vector3(0.0462f, -0.03f, 0.03f), Quaternion.Euler(10f, 0f, 0f), Vector3.one);
            Add(root, CharacterMeshes.Lathe(new[] { new Vector2(0.09f, 0f), new Vector2(0.17f, 0.05f), new Vector2(0.1967f, 0.13f) }, 28), p.Cool, new Vector3(0f, 0.28f, 0f), Quaternion.identity, Vector3.one);
            Add(root, CharacterMeshes.Lathe(new[] { new Vector2(0.1967f, 0.13f), new Vector2(0.2f, 0.14f), new Vector2(0.18f, 0.22f), new Vector2(0.1f, 0.28f) }, 28), p.Warm, new Vector3(0f, 0.28f, 0f), Quaternion.identity, Vector3.one);

            // The faceted crystal core (MV-584): 1.5x the old prism dimensions, both facets in the
            // BODY material (magenta) rather than p.Cool/p.Dark — the part of the silhouette that most
            // needs to read as "crystal", not "chassis".
            Add(root, CharacterMeshes.Prism(6, 0.2f, 0.3f, 0.26f, 0.3f, 22f), p.Warm, new Vector3(0f, 0.72f, 0f), Quaternion.identity, new Vector3(1.5f, 1.5f, 1.5f), "CrystalCore");
            Add(root, CharacterMeshes.Prism(6, 0.3f, 0.13f, 0.3f, 0.34f, -18f), p.Warm, new Vector3(0f, 1f, 0f), Quaternion.identity, new Vector3(1.5f, 1.5f, 1.5f), "CrystalCore");

            Add(root, CharacterMeshes.Lathe(new[] { new Vector2(0.21f, 0f), new Vector2(0.235f, 0.03f), new Vector2(0.2f, 0.07f) }, 12), p.Gold, new Vector3(0f, 0.855f, 0f), Quaternion.identity, Vector3.one);
            Add(root, CharacterMeshes.Lathe(new[] { new Vector2(0.1f, 0f), new Vector2(0.115f, 0.025f), new Vector2(0.08f, 0.06f) }, 10), p.Dark, new Vector3(0f, 1.16f, -0.01f), Quaternion.identity, Vector3.one);
            Add(root, CharacterMeshes.Lathe(new[] { new Vector2(0.1008f, 0f), new Vector2(0.1544f, 0.0158f), new Vector2(0.1625f, 0.0325f), new Vector2(0.1463f, 0.0525f) }, 24), p.Dark, new Vector3(0f, 0.86f, 0.245f), Quaternion.Euler(46f, 0f, 0f), Vector3.one);
            eyes.Add(Lens(root, CharacterMeshes.Sphere(20), new Vector3(0f, 0.8774f, 0.263f), Quaternion.Euler(-44f, 0f, 0f), new Vector3(0.1938f, 0.1938f, 0.0625f)));
            Add(root, CharacterMeshes.Beam(0.22f, 0.016f, 0.007f, 5), p.Dark, new Vector3(-0.09f, 1.25f, 0.02f), Quaternion.Euler(0f, 0f, 18f), Vector3.one);
            Add(root, CharacterMeshes.Sphere(10), p.Gold, new Vector3(-0.158f, 1.36f, 0.02f), Quaternion.identity, new Vector3(0.03f, 0.03f, 0.03f));
            Add(root, CharacterMeshes.Beam(0.14f, 0.016f, 0.007f, 5), p.Dark, new Vector3(0.1f, 1.19f, -0.05f), Quaternion.Euler(8f, 0f, -13f), Vector3.one);

            // Three floating crystal shards (MV-584), orbit-offset around the core at head height — the
            // at-a-glance tell that this one is not a wheeled robot: nothing else in the roster has
            // detached parts hovering off its own silhouette.
            const float shardRadius = 0.34f;
            const float shardHeight = 0.95f;
            for (int i = 0; i < 3; i++)
            {
                float thetaDeg = i * 120f;
                float thetaRad = thetaDeg * Mathf.Deg2Rad;
                var shardPos = new Vector3(Mathf.Sin(thetaRad) * shardRadius, shardHeight, Mathf.Cos(thetaRad) * shardRadius);
                Add(root, CharacterMeshes.Prism(5, 0.03f, 0.07f, 0.11f, 0.2f, thetaDeg), p.Warm,
                    shardPos, Quaternion.Euler(20f, thetaDeg, 12f), Vector3.one, "Shard");
            }
        }

        /// <summary>Half the leg-beam length (0.34f/2) — the Beam mesh is centred on its own local
        /// origin (see <see cref="CharacterMeshes.Beam"/>/<c>Prism</c>), so this is how far along that
        /// beam's local Y its two ends sit.</summary>
        private const float GunnerLegBeamHalfLength = 0.17f;

        /// <summary>Gunner — the other legged kind, and it earns them the same way — LungeSpeed is 0, it is a planted emplacement. Big head on a thin mast over a tripod.</summary>
        private static void BuildGunner(Transform root, in RobotPalette p,
                                    List<MeshRenderer> eyes, List<Transform> wheels, List<Transform> legs)
        {
            Transform leg1Beam = Add(root, CharacterMeshes.Beam(0.34f, 0.036f, 0.022f, 6), p.Dark, new Vector3(0f, 0.17f, 0.165f), Quaternion.Euler(22f, 0f, 0f), Vector3.one);
            Transform leg1Foot = Add(root, CharacterMeshes.Lathe(new[] { new Vector2(0.055f, 0f), new Vector2(0.038f, 0.03f), new Vector2(0.015f, 0.06f) }, 8), p.Dark, new Vector3(0f, 0.03f, 0.3f), Quaternion.identity, Vector3.one);
            legs.Add(AddLeg(root, leg1Beam, leg1Foot, GunnerLegBeamHalfLength));
            Transform leg2Beam = Add(root, CharacterMeshes.Beam(0.34f, 0.036f, 0.022f, 6), p.Dark, new Vector3(0.1429f, 0.17f, -0.0825f), Quaternion.Euler(-11f, 120f, -19.0526f), Vector3.one);
            Transform leg2Foot = Add(root, CharacterMeshes.Lathe(new[] { new Vector2(0.055f, 0f), new Vector2(0.038f, 0.03f), new Vector2(0.015f, 0.06f) }, 8), p.Dark, new Vector3(0.2598f, 0.03f, -0.15f), Quaternion.identity, Vector3.one);
            legs.Add(AddLeg(root, leg2Beam, leg2Foot, GunnerLegBeamHalfLength));
            Transform leg3Beam = Add(root, CharacterMeshes.Beam(0.34f, 0.036f, 0.022f, 6), p.Dark, new Vector3(-0.1429f, 0.17f, -0.0825f), Quaternion.Euler(-11f, 240f, 19.0526f), Vector3.one);
            Transform leg3Foot = Add(root, CharacterMeshes.Lathe(new[] { new Vector2(0.055f, 0f), new Vector2(0.038f, 0.03f), new Vector2(0.015f, 0.06f) }, 8), p.Dark, new Vector3(-0.2598f, 0.03f, -0.15f), Quaternion.identity, Vector3.one);
            legs.Add(AddLeg(root, leg3Beam, leg3Foot, GunnerLegBeamHalfLength));
            Add(root, CharacterMeshes.Lathe(new[] { new Vector2(0.16f, 0f), new Vector2(0.27f, 0.05f), new Vector2(0.285f, 0.11f) }, 28), p.Cool, new Vector3(0f, 0.34f, 0f), Quaternion.identity, Vector3.one);
            Add(root, CharacterMeshes.Lathe(new[] { new Vector2(0.285f, 0.11f), new Vector2(0.29f, 0.13f), new Vector2(0.24f, 0.2f), new Vector2(0.12f, 0.24f) }, 28), p.Warm, new Vector3(0f, 0.34f, 0f), Quaternion.identity, Vector3.one);
            Add(root, CharacterMeshes.Beam(0.26f, 0.042f, 0.055f, 7), p.Dark, new Vector3(0f, 0.7f, 0f), Quaternion.identity, Vector3.one);
            Add(root, CharacterMeshes.Lathe(new[] { new Vector2(0.075f, 0f), new Vector2(0.088f, 0.012f), new Vector2(0.075f, 0.026f) }, 14), p.Cool, new Vector3(0f, 0.62f, 0f), Quaternion.identity, Vector3.one);
            Add(root, CharacterMeshes.Lathe(new[] { new Vector2(0.075f, 0f), new Vector2(0.088f, 0.012f), new Vector2(0.075f, 0.026f) }, 14), p.Cool, new Vector3(0f, 0.7f, 0f), Quaternion.identity, Vector3.one);
            Add(root, CharacterMeshes.Lathe(new[] { new Vector2(0.075f, 0f), new Vector2(0.088f, 0.012f), new Vector2(0.075f, 0.026f) }, 14), p.Cool, new Vector3(0f, 0.78f, 0f), Quaternion.identity, Vector3.one);
            Add(root, CharacterMeshes.Lathe(new[] { new Vector2(0.1f, 0f), new Vector2(0.34f, 0.06f), new Vector2(0.38f, 0.14f), new Vector2(0.33f, 0.21f), new Vector2(0.14f, 0.25f) }, 22), p.Warm, new Vector3(0f, 0.86f, 0.01f), Quaternion.identity, Vector3.one);
            Add(root, CharacterMeshes.Lathe(new[] { new Vector2(0.28f, 0f), new Vector2(0.3f, 0.025f), new Vector2(0.26f, 0.055f) }, 22), p.Cool, new Vector3(0f, 1.11f, 0.01f), Quaternion.identity, Vector3.one);
            Add(root, CharacterMeshes.Beam(0.13f, 0.026f, 0.016f, 5), p.Dark, new Vector3(0.2949f, 0.98f, 0.2065f), Quaternion.Euler(96f, 55f, 0f), Vector3.one);
            Add(root, CharacterMeshes.Beam(0.13f, 0.026f, 0.016f, 5), p.Dark, new Vector3(0.0314f, 0.98f, -0.3586f), Quaternion.Euler(96f, 175f, 0f), Vector3.one);
            Add(root, CharacterMeshes.Beam(0.13f, 0.026f, 0.016f, 5), p.Dark, new Vector3(-0.3263f, 0.98f, 0.1521f), Quaternion.Euler(96f, 295f, 0f), Vector3.one);
            Add(root, CharacterMeshes.Lathe(new[] { new Vector2(0.1249f, 0f), new Vector2(0.1914f, 0.0195f), new Vector2(0.2015f, 0.0404f), new Vector2(0.1814f, 0.0651f) }, 24), p.Dark, new Vector3(0f, 0.99f, 0.31f), Quaternion.Euler(44f, 0f, 0f), Vector3.one);
            eyes.Add(Lens(root, CharacterMeshes.Sphere(20), new Vector3(0f, 1.0123f, 0.3315f), Quaternion.Euler(-46f, 0f, 0f), new Vector3(0.2402f, 0.2402f, 0.0775f)));
            Add(root, CharacterMeshes.Lathe(new[] { new Vector2(0.09f, 0f), new Vector2(0.1f, 0.012f), new Vector2(0.085f, 0.026f) }, 16), p.Gold, new Vector3(0f, 1.15f, 0.01f), Quaternion.identity, Vector3.one);
            Add(root, CharacterMeshes.Beam(0.24f, 0.016f, 0.007f, 5), p.Dark, new Vector3(0.13f, 1.26f, -0.09f), Quaternion.Euler(6f, 0f, -20f), Vector3.one);
            Add(root, CharacterMeshes.Sphere(10), p.Gold, new Vector3(0.2121f, 1.38f, -0.0649f), Quaternion.identity, new Vector3(0.03f, 0.03f, 0.03f));
            Add(root, CharacterMeshes.Beam(0.15f, 0.016f, 0.007f, 5), p.Dark, new Vector3(-0.1f, 1.195f, -0.11f), Quaternion.Euler(0f, 0f, 15f), Vector3.one);
        }

        /// <summary>Bolter (MV-578 rewrite of MV-539) — keeps the small-tier two-wheel drivetrain, but
        /// shares NO body silhouette with the Rusher any more: MV-539's version reused the Rusher's
        /// exact two body-cone lathes and only varied its small head spikes, invisible at gameplay
        /// camera distance. The body is now a low, wide drum (roughly twice the Rusher body's
        /// width-to-height ratio) wearing a crown of six large spikes radiating from its own equator —
        /// the drum itself is the spiked silhouette, not a smooth dome underneath a separate spiked
        /// head — plus a forward rod-launcher barrel as the weapon tell. One eye lens, per the roster's
        /// one-eye rule.</summary>
        private static void BuildBolter(Transform root, in RobotPalette p,
                                    List<MeshRenderer> eyes, List<Transform> wheels, List<Transform> legs)
        {
            wheels.Add(Add(root, CharacterMeshes.Lathe(new[] { new Vector2(0.0705f, -0.0675f), new Vector2(0.2021f, -0.0675f), new Vector2(0.235f, -0.0405f), new Vector2(0.235f, 0.0405f), new Vector2(0.2021f, 0.0675f), new Vector2(0.0705f, 0.0675f) }, 22), p.Dark, new Vector3(0f, 0.235f, -0.02f), Quaternion.Euler(0f, 0f, 90f), Vector3.one));
            wheels.Add(Add(root, CharacterMeshes.Lathe(new[] { new Vector2(0.1222f, -0.0243f), new Vector2(0.141f, 0f), new Vector2(0.1222f, 0.0243f) }, 16), p.Warm, new Vector3(0f, 0.235f, -0.02f), Quaternion.Euler(0f, 0f, 90f), Vector3.one));
            Add(root, CharacterMeshes.Beam(0.22f, 0.032f, 0.024f, 6), p.Dark, new Vector3(0f, 0.16f, 0.2f), Quaternion.Euler(60f, 0f, 0f), Vector3.one);

            // The drum: low and wide (diameter ~0.84m over a ~0.34m height — about twice the Rusher
            // body's own width-to-height ratio), not the Rusher's tall raked cone stack.
            Add(root, CharacterMeshes.Lathe(new[] { new Vector2(0.16f, 0f), new Vector2(0.36f, 0.05f), new Vector2(0.42f, 0.14f), new Vector2(0.414f, 0.16f) }, 28), p.Cool, new Vector3(0f, 0.32f, 0f), Quaternion.identity, Vector3.one);
            Add(root, CharacterMeshes.Lathe(new[] { new Vector2(0.414f, 0.16f), new Vector2(0.4f, 0.22f), new Vector2(0.28f, 0.28f), new Vector2(0.15f, 0.34f) }, 28), p.Warm, new Vector3(0f, 0.32f, 0f), Quaternion.identity, Vector3.one);

            // Six large spikes (height 0.52 — over 2x MV-539's biggest head spike at 0.22) radiating
            // from the drum's own equator (world y ~0.46, its widest point), 60 degrees apart and
            // offset 30 degrees off dead-ahead so none of them collide with the eye/barrel up front.
            const float spikeRadius = 0.40f;
            const float spikeEquatorY = 0.46f;
            for (int i = 0; i < 6; i++)
            {
                float thetaDeg = 30f + i * 60f;
                float thetaRad = thetaDeg * Mathf.Deg2Rad;
                var spikePos = new Vector3(Mathf.Sin(thetaRad) * spikeRadius, spikeEquatorY, Mathf.Cos(thetaRad) * spikeRadius);
                Add(root, CharacterMeshes.Prism(4, 0.10f, 0.006f, 0.52f, 0.1f, 0f), p.Warm,
                    spikePos, Quaternion.Euler(78f, thetaDeg, 0f), Vector3.one, "Spike");
            }

            // Eye socket, on the drum's front face.
            Add(root, CharacterMeshes.Lathe(new[] { new Vector2(0.1008f, 0f), new Vector2(0.1544f, 0.0158f), new Vector2(0.1625f, 0.0325f), new Vector2(0.1463f, 0.0525f) }, 24), p.Dark, new Vector3(0f, 0.62f, 0.26f), Quaternion.Euler(50f, 0f, 0f), Vector3.one);
            eyes.Add(Lens(root, CharacterMeshes.Sphere(20), new Vector3(0f, 0.6361f, 0.2792f), Quaternion.Euler(-40f, 0f, 0f), new Vector3(0.1938f, 0.1938f, 0.0625f)));

            // The weapon tell: one forward rod-launcher barrel at eye level, pointing straight down the
            // robot's own +Z (the direction BolterBolt.Fire's aim always resolves to before rotation).
            Add(root, CharacterMeshes.Beam(0.42f, 0.055f, 0.04f, 8), p.Dark, new Vector3(0f, 0.62f, 0.51f), Quaternion.Euler(90f, 0f, 0f), Vector3.one, "Barrel");
            Add(root, CharacterMeshes.Sphere(10), p.Gold, new Vector3(0f, 0.62f, 0.72f), Quaternion.identity, new Vector3(0.032f, 0.032f, 0.032f));
        }

        /// <summary>Grate Lurker (MV-688) — hand-authored, same exception as <see cref="BuildBolter"/>
        /// above (robot-gen-mesh.html is an interactive browser tool this worker cannot drive
        /// headlessly). No wheels, no legs: it never walks, only telescopes up out of a grate and back
        /// down. A thin, tall spindle — the cool lower half and the oil-black warm upper collar meeting
        /// at a gold filigree ring around the "neck" — with one eye lens near the top, per the roster's
        /// one-eye rule.</summary>
        private static void BuildLurker(Transform root, in RobotPalette p,
                                    List<MeshRenderer> eyes, List<Transform> wheels, List<Transform> legs)
        {
            Add(root, CharacterMeshes.Lathe(new[] { new Vector2(0.02f, 0f), new Vector2(0.20f, 0.08f), new Vector2(0.22f, 0.35f), new Vector2(0.19f, 0.55f) }, 20), p.Cool, new Vector3(0f, 0f, 0f), Quaternion.identity, Vector3.one);
            Add(root, CharacterMeshes.Lathe(new[] { new Vector2(0.19f, 0.55f), new Vector2(0.15f, 0.75f), new Vector2(0.09f, 0.95f), new Vector2(0.05f, 1.08f) }, 20), p.Warm, new Vector3(0f, 0f, 0f), Quaternion.identity, Vector3.one);

            // The one Tier-1 gold tell, at the join between the cool lower body and the oil-black collar.
            Add(root, CharacterMeshes.Lathe(new[] { new Vector2(0.19f, -0.015f), new Vector2(0.24f, 0f), new Vector2(0.19f, 0.015f) }, 24), p.Gold, new Vector3(0f, 0.55f, 0f), Quaternion.identity, Vector3.one);

            eyes.Add(Lens(root, CharacterMeshes.Sphere(20), new Vector3(0f, 0.92f, 0.08f), Quaternion.Euler(-30f, 0f, 0f), new Vector3(0.09f, 0.09f, 0.05f)));
        }

        /// <summary>Pipe Turret (MV-691) — hand-authored, same exception as <see cref="BuildBolter"/>/
        /// <see cref="BuildLurker"/> above (robot-gen-mesh.html is an interactive browser tool this
        /// worker cannot drive headlessly). No wheels, no legs: it is static and wall-mounted, so there
        /// is nothing here for a drivetrain or a gait to animate. A short pipe stub base (the ticket's
        /// own "mounted look") under a squat gunmetal drum, a forward coolant nozzle at status-light
        /// height, and one cyan status-light lens, per the roster's one-eye rule.</summary>
        private static void BuildTurret(Transform root, in RobotPalette p,
                                    List<MeshRenderer> eyes, List<Transform> wheels, List<Transform> legs)
        {
            // The stub base — a short pipe the drum sits on, reading "mounted" rather than "standing".
            Add(root, CharacterMeshes.Lathe(new[] { new Vector2(0.14f, 0f), new Vector2(0.16f, 0.02f), new Vector2(0.15f, 0.16f), new Vector2(0.13f, 0.18f) }, 16), p.Dark, new Vector3(0f, 0f, 0f), Quaternion.identity, Vector3.one, "Stub");

            // The gunmetal drum — low and wide, like the Bolter's own body but shorter, since this
            // kind never has to read as a mover.
            Add(root, CharacterMeshes.Lathe(new[] { new Vector2(0.13f, 0f), new Vector2(0.3f, 0.06f), new Vector2(0.34f, 0.2f), new Vector2(0.32f, 0.3f) }, 24), p.Cool, new Vector3(0f, 0.18f, 0f), Quaternion.identity, Vector3.one);
            Add(root, CharacterMeshes.Lathe(new[] { new Vector2(0.32f, 0.3f), new Vector2(0.28f, 0.4f), new Vector2(0.18f, 0.46f), new Vector2(0.1f, 0.48f) }, 24), p.Warm, new Vector3(0f, 0.18f, 0f), Quaternion.identity, Vector3.one);

            // The coolant nozzle — a forward barrel at status-light height, along the object's own
            // +Z, the same aim axis CorrosiveGlob.Fire resolves to before rotation (same idiom as
            // BolterBolt's barrel).
            Add(root, CharacterMeshes.Beam(0.34f, 0.05f, 0.032f, 8), p.Dark, new Vector3(0f, 0.48f, 0.26f), Quaternion.Euler(90f, 0f, 0f), Vector3.one, "Nozzle");
            Add(root, CharacterMeshes.Sphere(10), p.Gold, new Vector3(0f, 0.48f, 0.43f), Quaternion.identity, new Vector3(0.028f, 0.028f, 0.028f));

            // The cyan status light (the ticket's own colour call, stamped in by RobotEnemy.Apply's
            // TurretEyeColor) — one lens, per the roster's one-eye rule.
            eyes.Add(Lens(root, CharacterMeshes.Sphere(20), new Vector3(0f, 0.6f, 0.16f), Quaternion.identity, new Vector3(0.09f, 0.09f, 0.06f)));
        }

        /// <summary>Sludge Drone (MV-705) — hand-authored, same exception as <see cref="BuildBolter"/>/
        /// <see cref="BuildLurker"/>/<see cref="BuildTurret"/> above. A near-spherical leaking-coolant
        /// orb (the design reference's own silhouette) on four short legs radiating from its underside
        /// — <see cref="AddLeg"/>'s hip pivots give it to <see cref="MaxWorlds.VFX.LegGaitDriver"/>'s
        /// existing generic gait for free, which is the ticket's own "waddle": a legged, wheel-less
        /// walker rocks with every step in a way no wheeled kind in the roster does, with no bespoke
        /// animation of its own. A drooping coolant hose off one flank is the ticket's own "dripping
        /// hose" detail; one eye lens, per the roster's one-eye rule.</summary>
        private static void BuildSludger(Transform root, in RobotPalette p,
                                    List<MeshRenderer> eyes, List<Transform> wheels, List<Transform> legs)
        {
            for (int i = 0; i < 4; i++)
            {
                float thetaDeg = 45f + i * 90f;
                float thetaRad = thetaDeg * Mathf.Deg2Rad;
                var hipDir = new Vector3(Mathf.Sin(thetaRad), 0f, Mathf.Cos(thetaRad));
                Vector3 beamPos = new Vector3(hipDir.x * 0.18f, 0.14f, hipDir.z * 0.18f);
                Transform legBeam = Add(root, CharacterMeshes.Beam(0.22f, 0.03f, 0.022f, 6), p.Dark,
                    beamPos, Quaternion.Euler(28f, thetaDeg, 0f), Vector3.one);
                Vector3 footPos = new Vector3(hipDir.x * 0.32f, 0.02f, hipDir.z * 0.32f);
                Transform legFoot = Add(root, CharacterMeshes.Lathe(new[] { new Vector2(0.045f, 0f), new Vector2(0.03f, 0.025f), new Vector2(0.012f, 0.05f) }, 8), p.Dark,
                    footPos, Quaternion.identity, Vector3.one, "Foot");
                legs.Add(AddLeg(root, legBeam, legFoot, 0.11f));
            }

            // The round leaking-coolant body — nearer a sphere than any wheeled kind's tapered cone stack.
            Add(root, CharacterMeshes.Lathe(new[] { new Vector2(0.08f, 0f), new Vector2(0.32f, 0.08f), new Vector2(0.4f, 0.26f), new Vector2(0.38f, 0.4f) }, 28), p.Cool, new Vector3(0f, 0.22f, 0f), Quaternion.identity, Vector3.one);
            Add(root, CharacterMeshes.Lathe(new[] { new Vector2(0.38f, 0.4f), new Vector2(0.33f, 0.5f), new Vector2(0.18f, 0.58f), new Vector2(0f, 0.6f) }, 28), p.Warm, new Vector3(0f, 0.22f, 0f), Quaternion.identity, Vector3.one);

            // The dripping-hose detail — a coolant hose drooping off the body's flank, with a single
            // drip bead at its tip.
            Add(root, CharacterMeshes.Beam(0.26f, 0.028f, 0.024f, 6), p.Dark, new Vector3(0.28f, 0.32f, 0.1f), Quaternion.Euler(0f, 0f, -58f), Vector3.one, "Hose");
            Add(root, CharacterMeshes.Sphere(10), p.Cool, new Vector3(0.36f, 0.14f, 0.14f), Quaternion.identity, new Vector3(0.045f, 0.045f, 0.045f));

            Add(root, CharacterMeshes.Lathe(new[] { new Vector2(0.1f, 0f), new Vector2(0.153f, 0.0157f), new Vector2(0.161f, 0.0323f), new Vector2(0.145f, 0.0522f) }, 24), p.Dark, new Vector3(0f, 0.66f, 0.24f), Quaternion.Euler(48f, 0f, 0f), Vector3.one);
            eyes.Add(Lens(root, CharacterMeshes.Sphere(20), new Vector3(0f, 0.6774f, 0.263f), Quaternion.Euler(-42f, 0f, 0f), new Vector3(0.19f, 0.19f, 0.06f)));

            Add(root, CharacterMeshes.Sphere(10), p.Gold, new Vector3(-0.12f, 0.58f, 0.2f), Quaternion.identity, new Vector3(0.03f, 0.03f, 0.03f));
        }

        /// <summary>Cart Charger (MV-707) — hand-authored, same exception as <see cref="BuildBolter"/>/
        /// <see cref="BuildLurker"/>/<see cref="BuildTurret"/>/<see cref="BuildSludger"/> above
        /// (robot-gen-mesh.html is an interactive browser tool this worker cannot drive headlessly).
        /// Two wheel axles under a long, low chassis — the same two-lathe-halves torso every other
        /// kind builds, stretched non-uniformly into the long box the ticket's own silhouette calls
        /// for — chrome-grey lower half, rust-orange upper half, a push-handle arcing up at the rear,
        /// a gold filigree line at the chassis seam (MV-695), and one red eye lens on the basket's
        /// forward face, per the roster's one-eye rule.</summary>
        private static void BuildCharger(Transform root, in RobotPalette p,
                                    List<MeshRenderer> eyes, List<Transform> wheels, List<Transform> legs)
        {
            // Rear axle — the handle end (-Z).
            wheels.Add(Add(root, CharacterMeshes.Lathe(new[] { new Vector2(0.0645f, -0.0725f), new Vector2(0.1849f, -0.0725f), new Vector2(0.215f, -0.0435f), new Vector2(0.215f, 0.0435f), new Vector2(0.1849f, 0.0725f), new Vector2(0.0645f, 0.0725f) }, 22), p.Dark, new Vector3(-0.4f, 0.215f, -0.5f), Quaternion.Euler(0f, 0f, 90f), Vector3.one));
            wheels.Add(Add(root, CharacterMeshes.Lathe(new[] { new Vector2(0.1118f, -0.0261f), new Vector2(0.129f, 0f), new Vector2(0.1118f, 0.0261f) }, 16), p.Warm, new Vector3(-0.4f, 0.215f, -0.5f), Quaternion.Euler(0f, 0f, 90f), Vector3.one));
            wheels.Add(Add(root, CharacterMeshes.Lathe(new[] { new Vector2(0.0645f, -0.0725f), new Vector2(0.1849f, -0.0725f), new Vector2(0.215f, -0.0435f), new Vector2(0.215f, 0.0435f), new Vector2(0.1849f, 0.0725f), new Vector2(0.0645f, 0.0725f) }, 22), p.Dark, new Vector3(0.4f, 0.215f, -0.5f), Quaternion.Euler(0f, 0f, 90f), Vector3.one));
            wheels.Add(Add(root, CharacterMeshes.Lathe(new[] { new Vector2(0.1118f, -0.0261f), new Vector2(0.129f, 0f), new Vector2(0.1118f, 0.0261f) }, 16), p.Warm, new Vector3(0.4f, 0.215f, -0.5f), Quaternion.Euler(0f, 0f, 90f), Vector3.one));

            // Front axle — the basket end (+Z).
            wheels.Add(Add(root, CharacterMeshes.Lathe(new[] { new Vector2(0.0645f, -0.0725f), new Vector2(0.1849f, -0.0725f), new Vector2(0.215f, -0.0435f), new Vector2(0.215f, 0.0435f), new Vector2(0.1849f, 0.0725f), new Vector2(0.0645f, 0.0725f) }, 22), p.Dark, new Vector3(-0.4f, 0.215f, 0.5f), Quaternion.Euler(0f, 0f, 90f), Vector3.one));
            wheels.Add(Add(root, CharacterMeshes.Lathe(new[] { new Vector2(0.1118f, -0.0261f), new Vector2(0.129f, 0f), new Vector2(0.1118f, 0.0261f) }, 16), p.Warm, new Vector3(-0.4f, 0.215f, 0.5f), Quaternion.Euler(0f, 0f, 90f), Vector3.one));
            wheels.Add(Add(root, CharacterMeshes.Lathe(new[] { new Vector2(0.0645f, -0.0725f), new Vector2(0.1849f, -0.0725f), new Vector2(0.215f, -0.0435f), new Vector2(0.215f, 0.0435f), new Vector2(0.1849f, 0.0725f), new Vector2(0.0645f, 0.0725f) }, 22), p.Dark, new Vector3(0.4f, 0.215f, 0.5f), Quaternion.Euler(0f, 0f, 90f), Vector3.one));
            wheels.Add(Add(root, CharacterMeshes.Lathe(new[] { new Vector2(0.1118f, -0.0261f), new Vector2(0.129f, 0f), new Vector2(0.1118f, 0.0261f) }, 16), p.Warm, new Vector3(0.4f, 0.215f, 0.5f), Quaternion.Euler(0f, 0f, 90f), Vector3.one));

            // The chassis/basket — chrome-grey lower half, rust-orange upper half, stretched into a
            // long box (the ticket's own 1.1/1.0/1.4 body proportions).
            Add(root, CharacterMeshes.Lathe(new[] { new Vector2(0.3f, 0f), new Vector2(0.42f, 0.06f), new Vector2(0.45f, 0.22f), new Vector2(0.44f, 0.3f) }, 24), p.Cool, new Vector3(0f, 0.32f, 0f), Quaternion.identity, new Vector3(0.75f, 1f, 1.55f));
            Add(root, CharacterMeshes.Lathe(new[] { new Vector2(0.44f, 0.3f), new Vector2(0.42f, 0.4f), new Vector2(0.3f, 0.46f), new Vector2(0.14f, 0.5f) }, 24), p.Warm, new Vector3(0f, 0.32f, 0f), Quaternion.identity, new Vector3(0.75f, 1f, 1.55f));

            // The gold filigree line (MV-695) — a thin ring wrapping the chassis at the seam where
            // the chrome-grey lower half meets the rust-orange upper half, the same "one gold part"
            // Tier-2 tell every other Stormdrain kind already carries (Sludger's rivet, Lurker's neck
            // ring, Turret's nozzle cap). Shares the chassis halves' own origin and non-uniform scale
            // so the ring's ellipse hugs their seam exactly rather than reading as a separate circle.
            Add(root, CharacterMeshes.Lathe(new[] { new Vector2(0.44f, -0.012f), new Vector2(0.47f, 0f), new Vector2(0.44f, 0.012f) }, 24), p.Gold, new Vector3(0f, 0.62f, 0f), Quaternion.identity, new Vector3(0.75f, 1f, 1.55f));

            // The push handle, arcing up from the chassis at the rear.
            Add(root, CharacterMeshes.Beam(0.5f, 0.045f, 0.03f, 8), p.Dark, new Vector3(0f, 0.62f, -0.68f), Quaternion.Euler(-40f, 0f, 0f), Vector3.one);

            // The single red eye lens, on the basket's forward face.
            eyes.Add(Lens(root, CharacterMeshes.Sphere(20), new Vector3(0f, 0.55f, 0.68f), Quaternion.identity, new Vector3(0.16f, 0.16f, 0.06f)));
        }

        /// <summary>Skitter (MV-1224) — hand-authored, same exception as <see cref="BuildBolter"/>/
        /// <see cref="BuildLurker"/>/<see cref="BuildTurret"/>/<see cref="BuildSludger"/>/
        /// <see cref="BuildCharger"/> above. Deliberately the smallest body in the roster (the ticket's
        /// own "it is meant to be tiny; do not scale it up to read better") — a single small two-tone
        /// lathe shell with a thin ring skirting its base (the ticket's own "soft cyan glow halo",
        /// readability for a body this small) and one oversized gold eye lens (the ticket's own "bright
        /// gold eye", coloured by <see cref="MaxWorlds.Enemies.RobotEnemy.Apply"/>'s own
        /// <c>SkitterEyeColor</c>). No wheels, no legs — it never walks between hops, so there is
        /// nothing here for a drivetrain or a gait to animate.</summary>
        private static void BuildSkitter(Transform root, in RobotPalette p,
                                    List<MeshRenderer> eyes, List<Transform> wheels, List<Transform> legs)
        {
            // The shell — two lathe halves, same "cool lower / warm upper" idiom as every other kind,
            // just scaled to the ticket's own 0.4 m silhouette.
            Add(root, CharacterMeshes.Lathe(new[] { new Vector2(0.02f, 0f), new Vector2(0.16f, 0.05f), new Vector2(0.18f, 0.18f), new Vector2(0.15f, 0.26f) }, 16), p.Cool, Vector3.zero, Quaternion.identity, Vector3.one);
            Add(root, CharacterMeshes.Lathe(new[] { new Vector2(0.15f, 0.26f), new Vector2(0.12f, 0.33f), new Vector2(0.06f, 0.38f), new Vector2(0.02f, 0.4f) }, 16), p.Warm, Vector3.zero, Quaternion.identity, Vector3.one);

            // The halo (the ticket's own "soft cyan glow halo") — a thin ring skirting the base, the
            // same Ring primitive AddStormdrainShoulderBand already uses.
            Add(root, CharacterMeshes.Ring(0.19f, 0.24f, 0.015f, 20), p.Warm, new Vector3(0f, 0.03f, 0f), Quaternion.identity, Vector3.one, "Halo");

            // The one bright gold eye (the ticket's own "bright gold eye") — oversized relative to the
            // body so it still reads at ~19px, per the roster's one-eye rule.
            eyes.Add(Lens(root, CharacterMeshes.Sphere(16), new Vector3(0f, 0.3f, 0.14f), Quaternion.Euler(-30f, 0f, 0f), new Vector3(0.09f, 0.09f, 0.04f)));
        }

        /// <summary>Tractor (MV-1238) — hand-authored, same exception as <see cref="BuildBolter"/>/
        /// <see cref="BuildLurker"/>/<see cref="BuildTurret"/>/<see cref="BuildSludger"/>/
        /// <see cref="BuildCharger"/>/<see cref="BuildSkitter"/>/<see cref="BuildBreaker"/> above. A
        /// squat, wide stub base (the ticket's own "Bruiser-sized") topped with a wide shallow dish
        /// angled up and forward — the ticket's own "emitter dish" — the same "stub + raised fixture"
        /// read <see cref="BuildTurret"/> already established for a static emplacement, stretched to
        /// the Bruiser's own wider footprint since this kind never has to read as a mover either
        /// (<see cref="MaxWorlds.Enemies.EnemyArchetype.Tractor"/>'s own MoveSpeed is 0). One green
        /// status lens at the dish's hub — the ticket's own "the dish glows ... green" tell, coloured by
        /// <see cref="MaxWorlds.Enemies.RobotEnemy.Apply"/>'s own <c>TractorDishColor</c> — per the
        /// roster's one-eye rule. The dashed pull beam itself (<see cref="RobotRig.UpdatePullVfx"/>) is
        /// drawn from the robot's own root, not from this dish, so its exact mount position is cosmetic
        /// only.</summary>
        private static void BuildTractor(Transform root, in RobotPalette p,
                                    List<MeshRenderer> eyes, List<Transform> wheels, List<Transform> legs)
        {
            // The stub base — squat and wide, same "mounted, not standing" read as the Turret's own
            // stub, stretched to the Bruiser's own footprint.
            Add(root, CharacterMeshes.Lathe(new[] { new Vector2(0.4f, 0f), new Vector2(0.44f, 0.04f), new Vector2(0.42f, 0.22f), new Vector2(0.38f, 0.26f) }, 20), p.Cool, Vector3.zero, Quaternion.identity, Vector3.one);
            Add(root, CharacterMeshes.Lathe(new[] { new Vector2(0.38f, 0.26f), new Vector2(0.34f, 0.34f), new Vector2(0.2f, 0.4f), new Vector2(0.1f, 0.42f) }, 20), p.Warm, Vector3.zero, Quaternion.identity, Vector3.one);

            // The emitter dish — a wide shallow lathe bowl, angled up and toward +Z (the aim axis every
            // other ranged kind's own muzzle/barrel uses).
            Add(root, CharacterMeshes.Lathe(new[] { new Vector2(0f, 0f), new Vector2(0.3f, 0.02f), new Vector2(0.34f, 0.08f), new Vector2(0.3f, 0.1f) }, 24), p.Dark, new Vector3(0f, 0.5f, 0.1f), Quaternion.Euler(-20f, 0f, 0f), Vector3.one, "Dish");

            // The single green status lens at the dish's hub.
            eyes.Add(Lens(root, CharacterMeshes.Sphere(16), new Vector3(0f, 0.5f, 0.14f), Quaternion.Euler(-20f, 0f, 0f), new Vector3(0.1f, 0.1f, 0.05f)));
        }

        /// <summary>Welder (MV-1244) — hand-authored, same exception as <see cref="BuildTractor"/>
        /// above. A small 0.7 m hull (the ticket's own silhouette) — same "cool lower / warm upper"
        /// shell idiom every other kind uses — with one torch arm swept forward-down off its right
        /// flank (the ticket's own "torch arm"), tipped with a small gold nozzle. One eye lens, per the
        /// roster's one-eye rule. The repair beam itself (<see cref="MaxWorlds.VFX.RobotRig.UpdateWelderBeamVfx"/>)
        /// is drawn from the robot's own root, not from this arm, so its exact mount position is
        /// cosmetic only.</summary>
        private static void BuildWelder(Transform root, in RobotPalette p,
                                    List<MeshRenderer> eyes, List<Transform> wheels, List<Transform> legs)
        {
            // The hull — two lathe halves, same "cool lower / warm upper" idiom as every other kind,
            // scaled to the ticket's own 0.7 m silhouette.
            Add(root, CharacterMeshes.Lathe(new[] { new Vector2(0.04f, 0f), new Vector2(0.26f, 0.08f), new Vector2(0.3f, 0.3f), new Vector2(0.24f, 0.42f) }, 18), p.Cool, Vector3.zero, Quaternion.identity, Vector3.one);
            Add(root, CharacterMeshes.Lathe(new[] { new Vector2(0.24f, 0.42f), new Vector2(0.18f, 0.54f), new Vector2(0.09f, 0.62f), new Vector2(0.03f, 0.66f) }, 18), p.Warm, Vector3.zero, Quaternion.identity, Vector3.one);

            // The torch arm — swept forward-down off the right flank, tipped with a small gold nozzle.
            Add(root, CharacterMeshes.Beam(0.32f, 0.035f, 0.028f, 6), p.Dark, new Vector3(0.2f, 0.32f, 0.12f), Quaternion.Euler(55f, -15f, 0f), Vector3.one, "TorchArm");
            Add(root, CharacterMeshes.Sphere(10), p.Gold, new Vector3(0.33f, 0.14f, 0.32f), Quaternion.identity, new Vector3(0.05f, 0.05f, 0.05f));

            // The one eye lens, per the roster's one-eye rule.
            eyes.Add(Lens(root, CharacterMeshes.Sphere(18), new Vector3(0f, 0.5f, 0.24f), Quaternion.Euler(-40f, 0f, 0f), new Vector3(0.12f, 0.12f, 0.055f)));
        }

        /// <summary>Half the Shield Projector's own leg-beam length — same "Beam is centred on its own
        /// local origin" idiom as <see cref="GunnerLegBeamHalfLength"/>, which this is directly scaled
        /// from (see <see cref="BuildProjector"/>'s own doc comment).</summary>
        private const float ProjectorLegBeamHalfLength = 0.085f;

        /// <summary>Shield Projector (MV-1279) — hand-authored, same exception as <see cref="BuildWelder"/>
        /// above. The design image's own tripod-on-a-mast silhouette is <see cref="BuildGunner"/>'s own
        /// proven leg geometry (three short legs radiating at 0/120/240 degrees, with the one working
        /// tripod this roster already has), scaled 0.5x for the ticket's own "short legs" — a uniform
        /// scale keeps every leg's hip/foot topology <see cref="AddLeg"/> already resolves correctly,
        /// just smaller. A small 0.55 m hull sits on the tripod — the same "cool lower / warm upper"
        /// shell idiom every other kind uses, matching the image's own "base split pale-blue warm half /
        /// teal half" (the shared <see cref="RobotPalette.Cool"/> IS the pale-blue half; the kind's own
        /// hue, <see cref="RobotPalette.Warm"/>, supplies the teal — <see cref="MaxWorlds.VFX.CharacterSkin.RoleFor"/>
        /// has no case for <see cref="MaxWorlds.Enemies.EnemyKind.Projector"/> yet, same "no entry, falls
        /// through to the base Robot hue" footing <see cref="EnemyKind.Tractor"/>/<see cref="EnemyKind.Welder"/>
        /// already stand on, which happens to read as teal already). A thin mast (<c>p.Dark</c>) rises
        /// from the hull to ~2.3 m — the ticket's own "the tallest robot in the pack" — topped with a
        /// shallow lens-shaped dish reaching ~2.5 m total. The image's dish is white; no dedicated white
        /// material exists in <see cref="RobotPalette"/> (every other kind's dish/lens accents reuse
        /// <c>Cool</c>/<c>Dark</c>/<c>Gold</c> rather than owning a new shared material — see
        /// <see cref="BuildTractor"/>'s own dish, built from <c>p.Dark</c>), so the dish reuses
        /// <c>p.Cool</c> (the closest pale tone already shared by the whole roster) rather than adding
        /// one — acceptable under BUILD MODE: INDICATIVE, where the image is the reference for the
        /// result but is not itself the specification. One gold eye lens, OFF-CENTRE on the base (the
        /// ticket's own "gold off-centre eye on the base"), per the roster's one-eye rule — the dome
        /// itself (and its own look) is P2, not built here.</summary>
        private static void BuildProjector(Transform root, in RobotPalette p,
                                    List<MeshRenderer> eyes, List<Transform> wheels, List<Transform> legs)
        {
            // The tripod — BuildGunner's own leg geometry, uniformly scaled 0.5x (position, beam length
            // and foot profile alike), so AddLeg's hip/foot math — already proven correct there — still
            // resolves correctly here, just smaller.
            Transform leg1Beam = Add(root, CharacterMeshes.Beam(0.17f, 0.018f, 0.011f, 6), p.Dark, new Vector3(0f, 0.085f, 0.0825f), Quaternion.Euler(22f, 0f, 0f), Vector3.one);
            Transform leg1Foot = Add(root, CharacterMeshes.Lathe(new[] { new Vector2(0.0275f, 0f), new Vector2(0.019f, 0.015f), new Vector2(0.0075f, 0.03f) }, 8), p.Dark, new Vector3(0f, 0.015f, 0.15f), Quaternion.identity, Vector3.one);
            legs.Add(AddLeg(root, leg1Beam, leg1Foot, ProjectorLegBeamHalfLength));
            Transform leg2Beam = Add(root, CharacterMeshes.Beam(0.17f, 0.018f, 0.011f, 6), p.Dark, new Vector3(0.07145f, 0.085f, -0.04125f), Quaternion.Euler(-11f, 120f, -19.0526f), Vector3.one);
            Transform leg2Foot = Add(root, CharacterMeshes.Lathe(new[] { new Vector2(0.0275f, 0f), new Vector2(0.019f, 0.015f), new Vector2(0.0075f, 0.03f) }, 8), p.Dark, new Vector3(0.1299f, 0.015f, -0.075f), Quaternion.identity, Vector3.one);
            legs.Add(AddLeg(root, leg2Beam, leg2Foot, ProjectorLegBeamHalfLength));
            Transform leg3Beam = Add(root, CharacterMeshes.Beam(0.17f, 0.018f, 0.011f, 6), p.Dark, new Vector3(-0.07145f, 0.085f, -0.04125f), Quaternion.Euler(-11f, 240f, 19.0526f), Vector3.one);
            Transform leg3Foot = Add(root, CharacterMeshes.Lathe(new[] { new Vector2(0.0275f, 0f), new Vector2(0.019f, 0.015f), new Vector2(0.0075f, 0.03f) }, 8), p.Dark, new Vector3(-0.1299f, 0.015f, -0.075f), Quaternion.identity, Vector3.one);
            legs.Add(AddLeg(root, leg3Beam, leg3Foot, ProjectorLegBeamHalfLength));

            // The hull — two lathe halves, same "cool lower / warm upper" idiom as every other kind,
            // sitting atop the tripod.
            const float hullY = 0.17f;
            Add(root, CharacterMeshes.Lathe(new[] { new Vector2(0.02f, 0f), new Vector2(0.14f, 0.05f), new Vector2(0.16f, 0.16f), new Vector2(0.13f, 0.22f) }, 18), p.Cool, new Vector3(0f, hullY, 0f), Quaternion.identity, Vector3.one);
            Add(root, CharacterMeshes.Lathe(new[] { new Vector2(0.13f, 0.22f), new Vector2(0.1f, 0.28f), new Vector2(0.05f, 0.34f), new Vector2(0.02f, 0.38f) }, 18), p.Warm, new Vector3(0f, hullY, 0f), Quaternion.identity, Vector3.one);

            // The thin mast — rises from the hull's top to just under the dish, ~2.3 m up.
            const float hullTopY = hullY + 0.38f;
            const float dishBaseY = 2.3f;
            float mastLength = dishBaseY - hullTopY;
            Add(root, CharacterMeshes.Beam(mastLength, 0.035f, 0.02f, 8), p.Dark,
                new Vector3(0f, hullTopY + mastLength * 0.5f, 0f), Quaternion.identity, Vector3.one, "Mast");

            // The dish — a shallow lens shape capping the mast, reaching ~2.5 m total height.
            Add(root, CharacterMeshes.Lathe(new[] { new Vector2(0f, 0f), new Vector2(0.3f, 0.03f), new Vector2(0.32f, 0.1f), new Vector2(0.26f, 0.16f), new Vector2(0f, 0.2f) }, 24), p.Cool,
                new Vector3(0f, dishBaseY, 0f), Quaternion.identity, Vector3.one, "Dish");

            // The one gold eye lens, OFF-CENTRE on the base — the ticket's own "gold off-centre eye on
            // the base" — per the roster's one-eye rule.
            eyes.Add(Lens(root, CharacterMeshes.Sphere(16), new Vector3(0.09f, hullY + 0.26f, 0.13f), Quaternion.Euler(-40f, 0f, 0f), new Vector3(0.09f, 0.09f, 0.045f)));
        }

        /// <summary>Half the Jammer's own leg-beam length — same "Beam is centred on its own local
        /// origin" idiom as <see cref="ProjectorLegBeamHalfLength"/>.</summary>
        private const float JammerLegBeamHalfLength = 0.055f;

        /// <summary>Jammer (MV-1280) — hand-authored, same exception as <see cref="BuildProjector"/>
        /// above. A squat rounded drum (the ticket's own "squat rounded drum") sits on FOUR short legs
        /// at 0/90/180/270 degrees — unlike every tripod kind (<see cref="BuildGunner"/>/
        /// <see cref="BuildProjector"/>), each leg here is placed by composing
        /// <c>Quaternion.Euler(0, bearing, 0) * Quaternion.Euler(tilt, 0, 0)</c> directly rather than
        /// hand-baking a per-leg Euler+roll correction, so the same four-way-symmetric placement is
        /// trivially exact at each of the four bearings. The drum is the same "cool lower / warm upper"
        /// shell idiom every other kind uses, matching the image's own "pale-grey warm half / teal
        /// half" (the shared <see cref="RobotPalette.Cool"/> IS the pale tone; the kind's own hue,
        /// <see cref="RobotPalette.Warm"/>, supplies the teal — <see cref="MaxWorlds.VFX.CharacterSkin.RoleFor"/>
        /// has no case for <see cref="MaxWorlds.Enemies.EnemyKind.Jammer"/> yet, same "no entry, falls
        /// through to the base Robot hue" footing <see cref="EnemyKind.Tractor"/>/<see cref="EnemyKind.Welder"/>/
        /// <see cref="EnemyKind.Projector"/> already stand on). Three antenna spikes radiate from the
        /// drum's top at 0/120/240 degrees, each tipped with a small node — the ticket's own "three
        /// antenna spikes tipped with white nodes"; no dedicated white material exists in
        /// <see cref="RobotPalette"/> (same gap <see cref="BuildProjector"/>'s own dish hit), so the
        /// nodes reuse <c>p.Cool</c> (the closest pale tone already shared by the whole roster) rather
        /// than adding one — acceptable under BUILD MODE: INDICATIVE, where the image is the reference
        /// for the result but is not itself the specification. One gold eye lens, OFF-CENTRE on the
        /// drum (the ticket's own "gold off-centre eye"), per the roster's one-eye rule. The field
        /// effect itself (J2) is MV-1286, explicitly out of scope here.</summary>
        private static void BuildJammer(Transform root, in RobotPalette p,
                                    List<MeshRenderer> eyes, List<Transform> wheels, List<Transform> legs)
        {
            // Four short legs, radiating at 0/90/180/270 degrees — each placed by composing a yaw
            // (bearing) with a local pitch tilt, rather than a hand-baked per-leg Euler+roll correction.
            const float legRadius = 0.2f;
            const float legHipY = 0.065f;
            const float legFootRadius = 0.32f;
            const float legFootY = 0.015f;
            const float legTiltDeg = 24f;
            for (int i = 0; i < 4; i++)
            {
                float bearing = i * 90f;
                float rad = bearing * Mathf.Deg2Rad;
                Vector3 hipPos = new Vector3(Mathf.Sin(rad) * legRadius, legHipY, Mathf.Cos(rad) * legRadius);
                Vector3 footPos = new Vector3(Mathf.Sin(rad) * legFootRadius, legFootY, Mathf.Cos(rad) * legFootRadius);
                Quaternion legRot = Quaternion.Euler(0f, bearing, 0f) * Quaternion.Euler(legTiltDeg, 0f, 0f);

                Transform legBeam = Add(root, CharacterMeshes.Beam(0.11f, 0.02f, 0.013f, 6), p.Dark, hipPos, legRot, Vector3.one);
                Transform legFoot = Add(root, CharacterMeshes.Lathe(new[] { new Vector2(0.026f, 0f), new Vector2(0.018f, 0.014f), new Vector2(0.007f, 0.028f) }, 8), p.Dark, footPos, Quaternion.identity, Vector3.one);
                legs.Add(AddLeg(root, legBeam, legFoot, JammerLegBeamHalfLength));
            }

            // The drum — two lathe halves, same "cool lower / warm upper" idiom as every other kind,
            // squat and rounded per the ticket's own silhouette.
            Add(root, CharacterMeshes.Lathe(new[] { new Vector2(0.03f, 0f), new Vector2(0.26f, 0.05f), new Vector2(0.3f, 0.14f) }, 20), p.Cool, new Vector3(0f, 0.1f, 0f), Quaternion.identity, Vector3.one);
            Add(root, CharacterMeshes.Lathe(new[] { new Vector2(0.3f, 0.14f), new Vector2(0.26f, 0.23f), new Vector2(0.03f, 0.28f) }, 20), p.Warm, new Vector3(0f, 0.1f, 0f), Quaternion.identity, Vector3.one);

            // Three antenna spikes, radiating from the drum's top at 0/120/240 degrees, each tipped
            // with a small node (reuses p.Cool — see doc comment above for why there is no white).
            const float antennaBaseY = 0.37f;
            const float antennaTiltDeg = 14f;
            const float antennaLength = 0.2f;
            for (int i = 0; i < 3; i++)
            {
                float bearing = i * 120f;
                Quaternion antennaRot = Quaternion.Euler(0f, bearing, 0f) * Quaternion.Euler(antennaTiltDeg, 0f, 0f);
                Add(root, CharacterMeshes.Beam(antennaLength, 0.012f, 0.006f, 5), p.Dark,
                    new Vector3(0f, antennaBaseY, 0f), antennaRot, Vector3.one, "Antenna");
                Vector3 tip = new Vector3(0f, antennaBaseY, 0f) + antennaRot * new Vector3(0f, antennaLength * 0.5f, 0f);
                Add(root, CharacterMeshes.Sphere(10), p.Cool, tip, Quaternion.identity, new Vector3(0.028f, 0.028f, 0.028f), "AntennaNode");
            }

            // The one gold eye lens, OFF-CENTRE on the drum — the ticket's own "gold off-centre eye".
            eyes.Add(Lens(root, CharacterMeshes.Sphere(16), new Vector3(0.09f, 0.2f, 0.22f), Quaternion.Euler(-30f, 0f, 0f), new Vector3(0.08f, 0.08f, 0.04f)));
        }

